const wh = $("Vapi Inbound Webhook").first().json || {};
const body = wh.body || wh || {};
const msg = body.message || {};

let query = "";
let tool_call_id = "";
try {
  const calls = msg.toolCalls || msg.toolCallList || body.toolCalls || [];
  const tc = calls[0];
  if (tc) {
    tool_call_id = tc.id || "";
    let args = tc.function && tc.function.arguments;
    if (typeof args === "string") { try { args = JSON.parse(args); } catch (e) { args = {}; } }
    if (args) { query = args.query || args.question || args.text || ""; }
  }
} catch (e) {}

if (!query) { query = msg.transcript || body.transcript || body.query || body.text || ""; }

const call = msg.call || body.call || {};
const call_id = call.id || body.callId || msg.callId || "";
const caller_id = (call.customer && call.customer.number) || body.caller || body.from || (call.customer && call.customer.id) || "";
const session_id = body.session_id || call.id || call_id || caller_id || "unknown-session";
const timestamp = msg.timestamp || body.timestamp || new Date().toISOString();

let clean = String(query || "");
clean = clean.replace(/\b(uh|um|erm|uhh|umm)\b/gi, " ");
clean = clean.replace(/\s+/g, " ").trim();

const valid = clean.length > 0;

return [{ json: { query: clean, call_id, caller_id, session_id, tool_call_id, timestamp, valid, t_request: Date.now() } }];

const ex = $("Extract Call Data").first().json || {};
const cfg = $("Config").first().json || {};

let sessionRow = {};
try {
  const s = $("Load Session").all();
  if (s.length && s[0].json && Object.keys(s[0].json).length) sessionRow = s[0].json;
} catch (e) {}

let history = [];
try { if (sessionRow.history_json) history = JSON.parse(sessionRow.history_json); } catch (e) { history = []; }
if (!Array.isArray(history)) history = [];

const query = String(ex.query || "").trim();
const lastQuery = sessionRow.last_query || "";
const maxTurns = Number(cfg.max_history_turns || 3);

// Lightweight deterministic follow-up resolution using last query
const followupRe = /\b(it|its|that|those|these|this|one|there|then|they|them|he|she|him|her)\b/i;
const startFollow = /^(how long|how much|how many|when|where|why|and |what about|does it|do they|is it|are they|can i)/i;
const words = query.split(/\s+/).filter(Boolean);
let resolved_query = query;
if (history.length > 0 && lastQuery && (words.length <= 7) && (followupRe.test(query) || startFollow.test(query))) {
  resolved_query = lastQuery.replace(/[?.!]+\s*$/, "") + " - " + query;
}

// Deterministic out-of-scope detection (no LLM). Only flag when a clearly
// unrelated keyword is present AND no property keyword is present.
const oosRe = /\b(python|javascript|java|c\+\+|coding|code|program|programming|algorithm|compile|software|weather|forecast|temperature|sport|sports|football|cricket|basketball|joke|news|stock|stocks|bitcoin|crypto|recipe|cook|movie|song|lyrics|capital of|president|prime minister|integral|derivative|equation|calculus|multiply|divide|square root)\b/i;
const propRe = /\b(price|cost|rate|bhk|apartment|flat|home|size|sqft|sq ft|square feet|bedroom|bathroom|floor|balcony|park|parking|gym|pool|swimming|amenit|clubhouse|garden|security|pet|location|address|where|near|nearby|metro|school|hospital|available|availab|book|booking|visit|possession|carpet|builtup|built up|maintenance|emi|loan|door|window|facing|view|residence|sunrise|property|project|villa|unit|tower|configuration|payment|brochure|move in|ready)\b/i;
let out_of_scope = false;
if (oosRe.test(query) && !propRe.test(query)) out_of_scope = true;
const in_scope = !out_of_scope;

const history_text = history.slice(-(maxTurns * 2)).map(function (h) {
  return (h.role === "user" ? "Caller: " : "Assistant: ") + h.content;
}).join("\n") || "(none)";

return [{ json: Object.assign({}, ex, {
  config: cfg,
  original_query: query,
  resolved_query: resolved_query,
  in_scope: in_scope,
  out_of_scope: out_of_scope,
  history: history,
  history_text: history_text,
  prev_turn_count: Number(sessionRow.turn_count || 0),
  t_query_prepared: Date.now(),
}) }];

const cfg = $("Config").first().json || {};
const resp = $json || {};
let points = [];
try { points = (resp.result && resp.result.points) || resp.points || []; } catch (e) { points = []; }
if (!Array.isArray(points)) points = [];

const threshold = Number(cfg.similarity_threshold);
const topK = Number(cfg.top_k) || 5;
const minResults = Number(cfg.min_results || 1);

const seen = new Set();
const dedup = [];
for (const p of points) {
  const pl = (p && p.payload) || {};
  const text = String(pl.text || pl.content || pl.chunk || "").trim();
  if (!text) continue;
  const key = text.slice(0, 200);
  if (seen.has(key)) continue;
  seen.add(key);
  dedup.push({
    score: Number(p.score || 0),
    text: text,
    document: pl.document || pl.source || pl.file || "unknown",
    page: (pl.page !== undefined && pl.page !== null) ? pl.page : null,
    chunk_id: pl.chunk_id || p.id || null,
  });
}

dedup.sort(function (a, b) { return b.score - a.score; });
const ranked = dedup.slice(0, topK);
const relevant = ranked.filter(function (r) { return r.score >= threshold; });
const top_score = ranked.length ? ranked[0].score : 0;
const has_enough = relevant.length >= minResults && top_score >= threshold;

const context = (has_enough ? relevant : []).map(function (c, i) {
  return "SOURCE " + (i + 1) + "\nDocument: " + c.document + "\nPage: " + (c.page === null ? "n/a" : c.page) + "\n\n" + c.text;
}).join("\n\n");

return [{ json: Object.assign({}, $("Prepare Query").first().json, {
  retrieval_count: points.length,
  ranked: ranked,
  relevant_count: relevant.length,
  top_score: top_score,
  has_enough: has_enough,
  context: context,
  t_retrieval_done: Date.now(),
}) }];

let answer = "";
try { answer = $("LLM Grounded Answer").first().json.choices[0].message.content; } catch (e) { answer = ""; }

let verdict = { valid: false, safe_to_send: false, reason: "unparsed" };
try {
  const raw = $json.choices[0].message.content;
  verdict = (typeof raw === "string") ? JSON.parse(raw) : raw;
} catch (e) {}

const ok = verdict && verdict.valid === true && verdict.safe_to_send !== false && answer && answer.trim().length > 0;
const final_answer = ok ? answer : "I don't have that information in my available property details.";

return [{ json: Object.assign({}, $("Process Results").first().json, {
  final_answer: final_answer,
  validation: verdict,
  response_status: ok ? "success" : "validation_failed",
  t_answer_done: Date.now(),
}) }];

function g(name) { try { const a = $(name).all(); return (a.length && a[0].json) ? a[0].json : {}; } catch (e) { return {}; } }
const pq = g("Prepare Query");
const ex = g("Extract Call Data");
const cfg = pq.config || {};
const cur = $json || {};

let final_answer = cur.final_answer || "I'm sorry, I couldn't process that request.";
// Sanitize for a clean spoken response: single line, no markdown, no JSON fences.
final_answer = String(final_answer);
final_answer = final_answer.replace(/```[\s\S]*?```/g, " ");
final_answer = final_answer.replace(/[\r\n]+/g, " ");
final_answer = final_answer.replace(/[*_#`>]/g, "");
final_answer = final_answer.replace(/\s+/g, " ").trim();

const maxTurns = Number(cfg.max_history_turns || 3);
let history = Array.isArray(pq.history) ? pq.history.slice() : [];
history.push({ role: "user", content: pq.resolved_query || ex.query || "" });
history.push({ role: "assistant", content: final_answer });
if (history.length > maxTurns * 2) history = history.slice(-(maxTurns * 2));

const t_response = Date.now();
const t_request = Number(cur.t_request || pq.t_request || ex.t_request || 0);
const t_prepared = Number(cur.t_query_prepared || pq.t_query_prepared || 0);
const t_retrieval = Number(cur.t_retrieval_done || 0);
const t_answer = Number(cur.t_answer_done || 0);
const timings = {
  retrieval_latency_ms: (t_retrieval && t_prepared) ? (t_retrieval - t_prepared) : null,
  llm_latency_ms: (t_answer && t_retrieval) ? (t_answer - t_retrieval) : null,
  total_latency_ms: t_request ? (t_response - t_request) : null,
};

return [{ json: {
  session_id: pq.session_id || ex.session_id || "unknown-session",
  call_id: pq.call_id || ex.call_id || "",
  caller_id: pq.caller_id || ex.caller_id || "",
  tool_call_id: ex.tool_call_id || pq.tool_call_id || "",
  final_answer: final_answer,
  history_json: JSON.stringify(history),
  turn_count: (Number(pq.prev_turn_count || 0)) + 1,
  last_query: pq.resolved_query || ex.query || "",
  last_activity: new Date().toISOString(),
  top_score: (cur.top_score !== undefined) ? cur.top_score : 0,
  retrieval_count: (cur.retrieval_count !== undefined) ? cur.retrieval_count : 0,
  response_status: cur.response_status || "success",
  model: cfg.llm_model || "",
  timings: timings,
} }];

let answer = "";
try { answer = $("LLM Grounded Answer").first().json.choices[0].message.content; } catch (e) { answer = ""; }
answer = String(answer || "").trim();
const ok = answer.length > 0;
const final_answer = ok ? answer : "Sorry, I'm having trouble checking that information right now.";
return [{ json: Object.assign({}, $("Process Results").first().json, {
  final_answer: final_answer,
  response_status: ok ? "success" : "llm_error",
  t_answer_done: Date.now(),
}) }];
